// references
// https://paulbourke.net/geometry/supershape/
// https://en.wikipedia.org/wiki/Superformula

vec2 superFormula(float m, float n1, float n2, float n3, float phi){
   float r;
   float t1,t2;
   float a=1., b=1.;

   t1 = cos(m * phi / 4.) / a;
   t1 = abs(t1);
   t1 = pow(t1,n2);

   t2 = sin(m * phi / 4.) / b;
   t2 = abs(t2);
   t2 = pow(t2,n3);

   r = pow(t1+t2,1./n1);
   if (abs(r) == 0.) {
      return vec2(0.);
   } else {
      r = 1. / r;
      float x = r * cos(phi);
      float y = r * sin(phi);
      return vec2(x, y);
   }
}

float getMixed(vec2 uv){
    vec2 val = superFormula(sin(iTime / 1.5) * 6., 1., 1., 1., atan(uv.y, uv.x));
    float v = length(uv - val);
    val = superFormula(sin(iTime / 1.5) * 8., 3., 1., 1., atan(uv.y, uv.x));
    v = min(v, length(uv - val));
    val = superFormula(sin(iTime / 1.5) * 8., 1., 3., 3., atan(uv.y, uv.x));
    v = min(v, length(uv - val));
    val = superFormula(sin(iTime / 1.5) * 8., 0.8, 0.8, 0.8, atan(uv.y, uv.x));
    v = min(v, length(uv - val));
    val = superFormula((abs(sin(iTime * 1.5)) * 3.) + 3., 200., 260., 260., atan(uv.y, uv.x));
    v = min(v, length(uv - val));

    return v;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;    
    uv -= vec2(0.1, 0.8);    
    uv *= 8.;
    uv.x *= iResolution.x / iResolution.y;

    vec2 start = uv;
    vec2 offset = vec2(4.);

    vec2 val = superFormula(sin(iTime / 1.5) * 6., 1., 1., 1., atan(uv.y, uv.x));
    float v = length(uv - val);

    uv -= vec2(offset.x, 0.);
    val = superFormula(cos(iTime / 1.5) * 8., 3., 1., 1., atan(uv.y, uv.x));
    v = min(v, length(uv - val));

    uv -= vec2(offset.x, 0.);
    val = superFormula(sin(iTime / 1.5) * 8., 1., 3., 3., atan(uv.y, uv.x));
    v = min(v, length(uv - val));

    uv = start;
    uv += vec2(-0.2, offset.y);
    val = superFormula(sin(iTime / 1.5) * 8., 0.8, 0.8, 0.8, atan(uv.y, uv.x));
    v = min(v, length(uv - val));

    uv -= vec2(offset.x, 0.);
    val = superFormula((abs(sin(iTime * 1.5)) * 3.) + 3., 200., 260., 260., atan(uv.y, uv.x));
    v = min(v, length(uv - val));

    uv -= vec2(offset.x, 0.);
    v = min(v, getMixed(uv));

    //vec3 col = vec3(smoothstep(fwidth(length(start)), 0., v));    
    vec3 col = vec3(smoothstep(20. / iResolution.y, 0., v));


    fragColor = vec4(col,1.0);
}
